+                    }
+                }
+            }
+        } catch (Exception e) {
+            throw new SubCommandException(this.getClass().getSimpleName() + " command failed", e);
+        } finally {
+            adminExt.shutdown();
+        }
+    }
+
+    private void export(DefaultMQAdminExt adminExt, String brokerAddr, String brokerName, boolean dryRun) {
+        try {
