+                log.error("PopConsumerStore transfer from kvStore to fsStore failure", t);
+            }
+        }
+        log.info("PopConsumerStore transfer to fsStore finish, cost={}ms", stopwatch.elapsed(TimeUnit.MILLISECONDS));
+    }
